<style>.editor-card{background:rgba(7,28,34,.86);border:1px solid rgba(109,231,195,.35);border-radius:14px;padding:1.25rem}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.form-grid .wide{grid-column:1/-1}.form-grid label,.field-title{display:block}.form-grid input[type=text],.form-grid input[type=number],.form-grid textarea,.form-grid select{width:100%;padding:.55rem;border-radius:7px;border:1px solid #557078}.choice-row{display:grid;grid-template-columns:30px 1fr auto auto;gap:.5rem;align-items:center;margin:.4rem 0}.inline{display:inline-block!important;margin-right:1rem}.time-field{display:flex;gap:.5rem;align-items:center}.assignment-classes{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:.5rem}.boolean-fields,.written-fields{display:none}.form-grid:has(.question-type option[value="verdadero_falso"]:checked) .choice-fields{display:none}.form-grid:has(.question-type option[value="verdadero_falso"]:checked) .boolean-fields{display:block}.form-grid:has(.question-type option[value="respuesta_directa"]:checked) .choice-fields{display:none}.form-grid:has(.question-type option[value="respuesta_directa"]:checked) .written-fields{display:block}@media(max-width:700px){.form-grid{grid-template-columns:1fr}.choice-row{grid-template-columns:25px 1fr}.unique-check,.multiple-check{grid-column:auto}}</style>
<script>document.querySelectorAll('.question-form').forEach(function(form){const type=form.querySelector('.question-type');const refresh=function(){const value=type.value;form.querySelector('.choice-fields').style.display=['opcion_unica','seleccion_multiple'].includes(value)?'block':'none';form.querySelectorAll('.unique-check').forEach(el=>el.style.display=value==='opcion_unica'?'block':'none');form.querySelectorAll('.multiple-check').forEach(el=>el.style.display=value==='seleccion_multiple'?'block':'none');form.querySelector('.boolean-fields').style.display=value==='verdadero_falso'?'block':'none';form.querySelector('.written-fields').style.display=value==='respuesta_directa'?'block':'none'};type.addEventListener('change',refresh);refresh()});</script>
